(function() {
  var STORAGE_KEY = 'cardspoke_export_plus_config';
  var PANEL_ID = 'cs-export-plus-panel';
  var BTN_ID = 'cs-export-plus-btn';
  var HISTORY_LIMIT = 50;

  var config = {
    defaultFormat: 'markdown',
    includeMetadata: true,
    includeTags: true,
    includeTimestamps: true,
    customTemplate: null,
    exportHistory: []
  };

  var isPanelOpen = false;
  var availableFormats = ['markdown', 'csv', 'html', 'json'];

  function loadConfig() {
    try {
      var saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        var parsed = JSON.parse(saved);
        config.defaultFormat = parsed.defaultFormat || 'markdown';
        config.includeMetadata = parsed.includeMetadata !== false;
        config.includeTags = parsed.includeTags !== false;
        config.includeTimestamps = parsed.includeTimestamps !== false;
        config.customTemplate = parsed.customTemplate || null;
        config.exportHistory = parsed.exportHistory || [];
      }
    } catch (e) {
      console.warn('[Export Plus] Failed to load config:', e);
    }
  }

  function saveConfig() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
    } catch (e) {
      console.warn('[Export Plus] Failed to save config:', e);
    }
  }

  function clearConfig() {
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch (e) {
      console.warn('[Export Plus] Failed to clear config:', e);
    }
  }

  function addToHistory(entry) {
    config.exportHistory.unshift({
      timestamp: new Date().toISOString(),
      format: entry.format,
      cardCount: entry.cardCount,
      filename: entry.filename
    });
    if (config.exportHistory.length > HISTORY_LIMIT) {
      config.exportHistory = config.exportHistory.slice(0, HISTORY_LIMIT);
    }
    saveConfig();
  }

  function escapeHtml(str) {
    if (!str) return '';
    return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  }

  function escapeCsv(str) {
    if (!str) return '';
    if (str.indexOf(',') !== -1 || str.indexOf('"') !== -1 || str.indexOf('\n') !== -1) {
      return '"' + str.replace(/"/g, '""') + '"';
    }
    return str;
  }

  function exportToMarkdown(cards) {
    var lines = ['# CardSpoke Export', ''];
    lines.push('> Exported on ' + new Date().toLocaleString());
    lines.push('> Total cards: ' + cards.length);
    lines.push('');
    for (var i = 0; i < cards.length; i++) {
      var card = cards[i];
      lines.push('---');
      lines.push('');
      lines.push('## ' + (card.title || 'Untitled Card'));
      lines.push('');
      if (config.includeTags && card.tags && card.tags.length > 0) {
        lines.push('**Tags:** ' + card.tags.map(function(t) { return '`' + t + '`'; }).join(' '));
        lines.push('');
      }
      if (config.includeTimestamps && card.createdAt) {
        lines.push('**Created:** ' + card.createdAt);
        if (card.updatedAt) lines.push('**Updated:** ' + card.updatedAt);
        lines.push('');
      }
      lines.push(card.body || '');
      lines.push('');
    }
    return lines.join('\n');
  }

  function exportToCsv(cards) {
    var headers = ['Title', 'Body'];
    if (config.includeTags) headers.push('Tags');
    if (config.includeTimestamps) {
      headers.push('Created At');
      headers.push('Updated At');
    }
    if (config.includeMetadata) headers.push('ID');
    var rows = [headers.join(',')];
    for (var i = 0; i < cards.length; i++) {
      var card = cards[i];
      var row = [
        escapeCsv(card.title || ''),
        escapeCsv(card.body || '')
      ];
      if (config.includeTags) row.push(escapeCsv((card.tags || []).join('; ')));
      if (config.includeTimestamps) {
        row.push(escapeCsv(card.createdAt || ''));
        row.push(escapeCsv(card.updatedAt || ''));
      }
      if (config.includeMetadata) row.push(escapeCsv(card.id || ''));
      rows.push(row.join(','));
    }
    return rows.join('\n');
  }

  function exportToHtml(cards) {
    var html = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>CardSpoke Export</title>\n<style>\nbody { font-family: system-ui, -apple-system, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; background: #fafafa; color: #333; }\n.card { background: #fff; border: 1px solid #e0e0e0; border-radius: 8px; padding: 20px; margin-bottom: 16px; }\n.card h2 { margin: 0 0 8px; color: #222; }\n.card .tags { margin-bottom: 8px; }\n.card .tag { display: inline-block; background: #f0f0f0; padding: 2px 8px; border-radius: 10px; font-size: 12px; margin-right: 4px; color: #666; }\n.card .meta { font-size: 12px; color: #999; margin-bottom: 12px; }\n.card .body { line-height: 1.6; white-space: pre-wrap; }\n.header { text-align: center; margin-bottom: 30px; padding-bottom: 20px; border-bottom: 1px solid #e0e0e0; }\n.header h1 { margin: 0; }\n.header p { color: #888; font-size: 14px; }\n</style>\n</head>\n<body>\n<div class="header">\n<h1>CardSpoke Export</h1>\n<p>Exported on ' + escapeHtml(new Date().toLocaleString()) + ' &bull; ' + cards.length + ' cards</p>\n</div>\n';
    for (var i = 0; i < cards.length; i++) {
      var card = cards[i];
      html += '<div class="card">\n';
      html += '<h2>' + escapeHtml(card.title || 'Untitled Card') + '</h2>\n';
      if (config.includeTags && card.tags && card.tags.length > 0) {
        html += '<div class="tags">';
        for (var t = 0; t < card.tags.length; t++) {
          html += '<span class="tag">' + escapeHtml(card.tags[t]) + '</span>';
        }
        html += '</div>\n';
      }
      if (config.includeTimestamps && card.createdAt) {
        html += '<div class="meta">Created: ' + escapeHtml(card.createdAt);
        if (card.updatedAt) html += ' &bull; Updated: ' + escapeHtml(card.updatedAt);
        html += '</div>\n';
      }
      html += '<div class="body">' + escapeHtml(card.body || '') + '</div>\n';
      html += '</div>\n';
    }
    html += '</body>\n</html>';
    return html;
  }

  function exportToJson(cards) {
    var output = {
      exportedAt: new Date().toISOString(),
      cardCount: cards.length,
      cards: cards.map(function(card) {
        var c = { title: card.title || '', body: card.body || '' };
        if (config.includeTags) c.tags = card.tags || [];
        if (config.includeTimestamps) {
          c.createdAt = card.createdAt || null;
          c.updatedAt = card.updatedAt || null;
        }
        if (config.includeMetadata) c.id = card.id || null;
        return c;
      })
    };
    return JSON.stringify(output, null, 2);
  }

  function performExport(cards, format) {
    var content, mimeType, extension;
    switch (format) {
      case 'csv':
        content = exportToCsv(cards);
        mimeType = 'text/csv';
        extension = 'csv';
        break;
      case 'html':
        content = exportToHtml(cards);
        mimeType = 'text/html';
        extension = 'html';
        break;
      case 'json':
        content = exportToJson(cards);
        mimeType = 'application/json';
        extension = 'json';
        break;
      default:
        content = exportToMarkdown(cards);
        mimeType = 'text/markdown';
        extension = 'md';
        break;
    }
    var filename = 'cardspoke-export-' + new Date().toISOString().split('T')[0] + '.' + extension;
    triggerDownload(content, filename, mimeType);
    addToHistory({ format: format, cardCount: cards.length, filename: filename });
    console.log('[Export Plus] Exported', cards.length, 'cards as', format);
    return { content: content, filename: filename, format: format };
  }

  function triggerDownload(content, filename, mimeType) {
    try {
      var blob = new Blob([content], { type: mimeType + ';charset=utf-8' });
      var url = URL.createObjectURL(blob);
      var link = document.createElement('a');
      link.href = url;
      link.download = filename;
      link.style.display = 'none';
      document.body.appendChild(link);
      link.click();
      setTimeout(function() {
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
      }, 100);
    } catch (e) {
      console.error('[Export Plus] Download failed:', e);
    }
  }

  function renderPanel() {
    var panel = document.getElementById(PANEL_ID);
    if (!panel) return;
    var formatOptions = '';
    for (var f = 0; f < availableFormats.length; f++) {
      var fmt = availableFormats[f];
      var selected = fmt === config.defaultFormat ? ' selected' : '';
      formatOptions += '<option value="' + fmt + '"' + selected + '>' + fmt.charAt(0).toUpperCase() + fmt.slice(1) + '</option>';
    }
    var historyHtml = '';
    if (config.exportHistory.length > 0) {
      var recentHistory = config.exportHistory.slice(0, 10);
      for (var h = 0; h < recentHistory.length; h++) {
        var entry = recentHistory[h];
        var date = new Date(entry.timestamp).toLocaleDateString();
        var time = new Date(entry.timestamp).toLocaleTimeString();
        historyHtml += '<div style="display:flex;justify-content:space-between;padding:4px 0;font-size:11px;border-bottom:1px solid #f5f5f5;"><span style="color:#555;">' + entry.filename + '</span><span style="color:#aaa;">' + date + ' ' + time + '</span></div>';
      }
    } else {
      historyHtml = '<div style="font-size:12px;color:#bbb;text-align:center;padding:8px;">No exports yet</div>';
    }
    var contentEl = panel.querySelector('.cs-export-content');
    if (contentEl) {
      contentEl.innerHTML = '<div style="padding:16px;"><div style="margin-bottom:14px;"><label style="display:block;font-size:12px;font-weight:600;color:#555;margin-bottom:4px;">Format</label><select id="cs-export-format" style="width:100%;padding:6px 10px;border:1px solid #ddd;border-radius:6px;font-size:13px;background:#fff;">' + formatOptions + '</select></div><div style="margin-bottom:14px;"><div style="font-size:12px;font-weight:600;color:#555;margin-bottom:6px;">Options</div><label style="display:flex;align-items:center;margin-bottom:6px;font-size:12px;color:#666;cursor:pointer;"><input type="checkbox" id="cs-export-meta" ' + (config.includeMetadata ? 'checked' : '') + ' style="margin-right:6px;"> Include metadata</label><label style="display:flex;align-items:center;margin-bottom:6px;font-size:12px;color:#666;cursor:pointer;"><input type="checkbox" id="cs-export-tags" ' + (config.includeTags ? 'checked' : '') + ' style="margin-right:6px;"> Include tags</label><label style="display:flex;align-items:center;margin-bottom:6px;font-size:12px;color:#666;cursor:pointer;"><input type="checkbox" id="cs-export-timestamps" ' + (config.includeTimestamps ? 'checked' : '') + ' style="margin-right:6px;"> Include timestamps</label></div><button id="cs-export-run" style="width:100%;padding:10px;background:#4a90d9;color:#fff;border:none;border-radius:6px;font-size:13px;font-weight:500;cursor:pointer;margin-bottom:16px;">Export All Cards</button><div><div style="font-size:12px;font-weight:600;color:#555;margin-bottom:6px;">Export History</div><div style="max-height:150px;overflow-y:auto;">' + historyHtml + '</div></div></div>';
      var formatSelect = document.getElementById('cs-export-format');
      var metaCheck = document.getElementById('cs-export-meta');
      var tagsCheck = document.getElementById('cs-export-tags');
      var timestampsCheck = document.getElementById('cs-export-timestamps');
      var exportBtn = document.getElementById('cs-export-run');
      if (formatSelect) {
        formatSelect.addEventListener('change', function() {
          config.defaultFormat = this.value;
          saveConfig();
        });
      }
      if (metaCheck) {
        metaCheck.addEventListener('change', function() {
          config.includeMetadata = this.checked;
          saveConfig();
        });
      }
      if (tagsCheck) {
        tagsCheck.addEventListener('change', function() {
          config.includeTags = this.checked;
          saveConfig();
        });
      }
      if (timestampsCheck) {
        timestampsCheck.addEventListener('change', function() {
          config.includeTimestamps = this.checked;
          saveConfig();
        });
      }
      if (exportBtn) {
        exportBtn.addEventListener('click', function() {
          document.dispatchEvent(new CustomEvent('cardspoke:requestCards', {
            detail: {
              callback: function(cards) {
                performExport(cards || [], config.defaultFormat);
                renderPanel();
              }
            }
          }));
        });
      }
    }
  }

  function createUI() {
    if (document.getElementById(PANEL_ID)) return;
    var panel = document.createElement('div');
    panel.id = PANEL_ID;
    panel.style.cssText = 'position:fixed;top:60px;right:20px;width:340px;max-height:550px;background:#fff;border:1px solid #ddd;border-radius:10px;box-shadow:0 8px 30px rgba(0,0,0,0.12);z-index:9999;font-family:system-ui,-apple-system,sans-serif;display:none;flex-direction:column;overflow:hidden;';
    panel.innerHTML = '<div style="padding:10px 14px;border-bottom:1px solid #eee;display:flex;justify-content:space-between;align-items:center;"><span style="font-size:14px;font-weight:600;color:#333;">Export Plus</span><button id="cs-export-close" style="background:none;border:none;font-size:18px;color:#999;cursor:pointer;">&times;</button></div><div class="cs-export-content" style="overflow-y:auto;"></div>';
    document.body.appendChild(panel);
    document.getElementById('cs-export-close').addEventListener('click', togglePanel);
    var btn = document.createElement('button');
    btn.id = BTN_ID;
    btn.textContent = 'Export+';
    btn.style.cssText = 'position:fixed;bottom:60px;right:20px;padding:8px 16px;background:#2c7a3e;color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:500;cursor:pointer;z-index:9998;box-shadow:0 2px 10px rgba(44,122,62,0.3);transition:background 0.2s;';
    btn.addEventListener('click', togglePanel);
    btn.addEventListener('mouseenter', function() { btn.style.background = '#236830'; });
    btn.addEventListener('mouseleave', function() { btn.style.background = '#2c7a3e'; });
    document.body.appendChild(btn);
  }

  function togglePanel() {
    var panel = document.getElementById(PANEL_ID);
    if (!panel) return;
    isPanelOpen = !isPanelOpen;
    panel.style.display = isPanelOpen ? 'flex' : 'none';
    if (isPanelOpen) renderPanel();
  }

  function destroyUI() {
    var panel = document.getElementById(PANEL_ID);
    if (panel) panel.parentNode.removeChild(panel);
    var btn = document.getElementById(BTN_ID);
    if (btn) btn.parentNode.removeChild(btn);
    isPanelOpen = false;
  }

  CardSpoke_MODS.register({
    name: 'Export Plus',
    hooks: {
      onAppInit: function() {
        loadConfig();
        createUI();
        console.log('[Export Plus] Expansion initialized with default format:', config.defaultFormat);
      },
      onExport: function(exportData) {
        if (exportData && exportData.cards) {
          var result = performExport(exportData.cards, config.defaultFormat);
          if (isPanelOpen) renderPanel();
          return result;
        }
        return exportData;
      },
      onDisable: function() {
        destroyUI();
        console.log('[Export Plus] Expansion disabled, UI removed');
      },
      onUninstall: function() {
        destroyUI();
        clearConfig();
        console.log('[Export Plus] Expansion uninstalled, all data cleared');
      }
    }
  });
})()

css:
.cs-export-plus-panel {
  font-family: system-ui, -apple-system, sans-serif;
}

.cs-export-plus-panel select {
  background: var(--bg-input, #ffffff);
  color: var(--text-primary, #333333);
  border: 1px solid var(--accent-border, #dddddd);
}

.cs-export-plus-panel select:focus {
  border-color: var(--accent-primary, #4a90d9);
  box-shadow: 0 0 0 2px rgba(74, 144, 217, 0.15);
  outline: none;
}

.cs-export-plus-panel .export-btn {
  background: var(--accent-primary, #4a90d9);
  color: #ffffff;
  border: none;
  border-radius: 6px;
  padding: 10px;
  font-weight: 500;
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.cs-export-plus-panel .export-btn:hover {
  opacity: 0.9;
}

.cs-export-plus-panel .history-entry {
  padding: 4px 0;
  border-bottom: 1px solid var(--bg-hover, #f5f5f5);
  font-size: 11px;
  color: var(--text-secondary, #888888);
}

.cs-export-plus-panel .format-badge {
  display: inline-block;
  padding: 1px 6px;
  background: var(--bg-hover, #f0f0f0);
  border-radius: 3px;
  font-size: 10px;
  text-transform: uppercase;
  color: var(--text-muted, #aaaaaa);
}
